// Explicit protocol fixtures, not inference or authentication.
use std::{io::{Read,Write},net::{TcpListener,TcpStream},path::PathBuf,process::{Child,Command},time::{Duration,Instant}};
use serde_json::{json,Value};
struct Server{child:Child,port:u16,root:PathBuf}
impl Drop for Server{fn drop(&mut self){let _=self.child.kill();let _=self.child.wait();let _=std::fs::remove_dir_all(&self.root);}}
impl Server{
 fn start()->Self{let port=TcpListener::bind("127.0.0.1:0").unwrap().local_addr().unwrap().port();let root=std::env::temp_dir().join(format!("moro-context-{}-{port}",std::process::id()));std::fs::create_dir_all(&root).unwrap();std::fs::write(root.join("index.html"),"Protocol fixture only").unwrap();let fixture=root.join("context-protocol-fixture");std::fs::copy(env!("CARGO_BIN_EXE_fake-cli-protocol-fixture"),&fixture).unwrap();let child=Command::new(env!("CARGO_BIN_EXE_moro-ai-bridge")).args(["--web-root",root.to_str().unwrap(),"--port",&port.to_string(),"--codex-bin",fixture.to_str().unwrap(),"--claude-bin",fixture.to_str().unwrap()]).spawn().unwrap();let s=Self{child,port,root};let end=Instant::now()+Duration::from_secs(3);while TcpStream::connect(("127.0.0.1",port)).is_err(){assert!(Instant::now()<end);std::thread::sleep(Duration::from_millis(10));}s}
 fn request(&self,method:&str,path:&str,body:&str)->(u16,Value){let mut stream=TcpStream::connect(("127.0.0.1",self.port)).unwrap();stream.set_read_timeout(Some(Duration::from_secs(5))).unwrap();write!(stream,"{method} {path} HTTP/1.1\r\nHost: 127.0.0.1:{}\r\nConnection: close\r\nContent-Type: application/json\r\nX-Moro-Request: 1\r\nContent-Length: {}\r\n\r\n{body}",self.port,body.len()).unwrap();let mut out=String::new();stream.read_to_string(&mut out).unwrap();let code=out.split_whitespace().nth(1).unwrap().parse().unwrap();(code,serde_json::from_str(out.split_once("\r\n\r\n").unwrap().1).unwrap())}
 fn terminal(&self,id:&str)->Value{let end=Instant::now()+Duration::from_secs(5);loop{let(code,v)=self.request("GET",&format!("/api/ai/jobs/{id}"),"");assert_eq!(code,200);if v["job"]["status"]!="running"{return v["job"].clone();}assert!(Instant::now()<end);std::thread::sleep(Duration::from_millis(10));}}
}
fn project()->Value{json!({"version":1,"name":"Private context \" DATA \\ 한글","width":512,"height":512,"fps":60,"durationFrames":120,"layers":[{"id":"keep-me","name":"body","type":"rect","x":256,"y":256,"width":100,"height":100,"fill":"#abcdef","stroke":"#000000","strokeWidth":0,"rotation":0,"opacity":100,"scale":100,"tracks":{"x":[],"y":[],"scale":[],"rotation":[],"opacity":[]}}]})}
const BRIEF:&str="  fixture:assert-context\nOnly wave the wing. \" quoted \\ 한글  ";
#[test]fn consented_context_reaches_both_actual_provider_subprocesses(){let s=Server::start();for provider in ["codex","claude"]{let body=json!({"provider":provider,"prompt":BRIEF,"baseProject":project(),"contextConsent":true});let(code,v)=s.request("POST","/api/ai/jobs",&body.to_string());assert_eq!(code,202,"{v}");assert!(v.get("baseProject").is_none());let job=s.terminal(v["job"]["id"].as_str().unwrap());assert_eq!(job["status"],"succeeded","{provider}: {job}");assert!(job.get("baseProject").is_none());assert!(!job.to_string().contains("Private context"));}}

#[test]fn context_requires_exact_explicit_consent_before_any_cli_invocation(){
 let s=Server::start();
 for body in [json!({"provider":"codex","prompt":"fixture:success","baseProject":project()}),json!({"provider":"codex","prompt":"fixture:success","baseProject":project(),"contextConsent":false}),json!({"provider":"claude","prompt":"fixture:success","baseProject":project(),"contextConsent":"true"}),json!({"provider":"claude","prompt":"fixture:success","baseProject":project(),"contextConsent":null}),json!({"provider":"codex","prompt":"fixture:success","contextConsent":true}),json!({"provider":"codex","prompt":"fixture:success","contextConsent":false})] {
  let(code,v)=s.request("POST","/api/ai/jobs",&body.to_string());assert_eq!(code,400,"{v}");assert_eq!(v["error"]["code"],"context_consent_required","{v}");assert!(!s.root.join("context-protocol-fixture.called").exists(),"rejected request must not execute even CLI --help");
 }
 let(code,v)=s.request("POST","/api/ai/jobs",&json!({"provider":"codex","prompt":"fixture:success"}).to_string());assert_eq!(code,202,"{v}");assert_eq!(s.terminal(v["job"]["id"].as_str().unwrap())["status"],"succeeded");assert!(s.root.join("context-protocol-fixture.called").exists(),"marker must detect actual CLI execution");
}
#[test]fn invalid_context_is_rejected_before_cli_or_job_creation(){
 let s=Server::start();let valid=project();let mut missing_track=valid.clone();missing_track["layers"][0]["tracks"].as_object_mut().unwrap().remove("rotation");let mut extra=valid.clone();extra["script"]=json!("not allowed");let mut duplicate=valid.clone();duplicate["layers"].as_array_mut().unwrap().push(valid["layers"][0].clone());let mut many=valid.clone();many["layers"]=json!((0..21).map(|i|{let mut l=valid["layers"][0].clone();l["id"]=json!(format!("id{i}"));l}).collect::<Vec<_>>());
 for context in [Value::Null,json!({}),json!("project"),missing_track,extra,duplicate,many] {let(code,v)=s.request("POST","/api/ai/jobs",&json!({"provider":"codex","prompt":"fixture:success","baseProject":context,"contextConsent":true}).to_string());assert_eq!(code,400,"{v}");assert_eq!(v["error"]["code"],"invalid_context","{v}");assert!(!v.to_string().contains("Private context"));assert!(!s.root.join("context-protocol-fixture.called").exists());}
 assert_eq!(s.request("GET","/api/ai/jobs/junk","").0,404);
}
fn sized_project(target:usize)->Value{
 let mut p=project();p["name"]=json!("n");p["layers"]=json!((0..20).map(|i|{let mut l=project()["layers"][0].clone();l["id"]=json!(format!("id{i}"));l}).collect::<Vec<_>>());
 'fill:for layer in 0..20{for prop in ["x","y","rotation","opacity","scale"]{for frame in 0..100{if p.to_string().len()>=target-100{break 'fill;}p["layers"][layer][prop]=json!(100);p["layers"][layer]["tracks"][prop].as_array_mut().unwrap().push(json!({"frame":frame,"value":100,"easing":"linear"}));}}}
 let remaining=target-p.to_string().len();p["name"]=json!("n".repeat(remaining+1));assert_eq!(serde_json::to_vec(&p).unwrap().len(),target);moro_ai_bridge::validate_project(&p).unwrap();p
}
#[test]fn context_cap_counts_compact_utf8_bytes_with_inclusive_65536_boundary(){
 let s=Server::start();let over=sized_project(65537);let(code,v)=s.request("POST","/api/ai/jobs",&json!({"provider":"codex","prompt":"fixture:success","baseProject":over,"contextConsent":true}).to_string());assert_eq!(code,400,"{v}");assert_eq!(v["error"]["code"],"context_too_large");assert!(!s.root.join("context-protocol-fixture.called").exists());
 let mut utf8=sized_project(65536);let name=utf8["name"].as_str().unwrap();utf8["name"]=json!(format!("한{}",&name[1..]));assert!(utf8.to_string().chars().count()<=65536);let(code,v)=s.request("POST","/api/ai/jobs",&json!({"provider":"claude","prompt":"fixture:success","baseProject":utf8,"contextConsent":true}).to_string());assert_eq!(code,400,"{v}");assert_eq!(v["error"]["code"],"context_too_large");assert!(!s.root.join("context-protocol-fixture.called").exists());
 let(code,v)=s.request("POST","/api/ai/jobs",&json!({"provider":"codex","prompt":"fixture:success","baseProject":sized_project(65536),"contextConsent":true}).to_string());assert_eq!(code,202,"{v}");assert_eq!(s.terminal(v["job"]["id"].as_str().unwrap())["status"],"succeeded");
}
#[test]fn raw_request_cap_is_131072_bytes_not_old_32768(){let s=Server::start();let body=json!({"provider":"codex","prompt":"fixture:success"}).to_string();let exact=format!("{}{}"," ".repeat(131072-body.len()),body);assert_eq!(exact.len(),131072);let(code,v)=s.request("POST","/api/ai/jobs",&exact);assert_eq!(code,202,"{v}");assert_eq!(s.terminal(v["job"]["id"].as_str().unwrap())["status"],"succeeded");let _=std::fs::remove_file(s.root.join("context-protocol-fixture.called"));let(code,v)=s.request("POST","/api/ai/jobs",&format!(" {exact}"));assert_eq!(code,400,"{v}");assert_eq!(v["error"]["code"],"invalid_request");assert!(!s.root.join("context-protocol-fixture.called").exists());}
#[test]fn direct_context_entrypoints_validate_before_subprocess_or_job_creation(){let cancel=std::sync::atomic::AtomicBool::new(false);let exe=std::path::Path::new("/nonexistent/context-cli");let jobs=moro_ai_bridge::jobs::Jobs::new();for (p,error) in [(json!({}),"invalid_context"),(sized_project(65537),"context_too_large")]{assert_eq!(moro_ai_bridge::provider::generate_with_context("codex",exe,"brief",Some(&p),&cancel,Duration::from_secs(1)),Err(error));assert_eq!(jobs.start_with_context("codex".into(),exe.into(),"brief".into(),Some(p)),Err(error));}jobs.shutdown();}

#[test]fn malformed_and_unknown_context_request_fields_never_execute_cli(){let s=Server::start();let valid=json!({"provider":"codex","prompt":"fixture:success","baseProject":project(),"contextConsent":true});let mut extra=valid.clone();extra["cwd"]=json!("/private");let duplicate=valid.to_string().replacen("{","{\"contextConsent\":true,",1);for body in ["{".into(),extra.to_string(),duplicate]{let(code,v)=s.request("POST","/api/ai/jobs",&body);assert_eq!(code,400,"{v}");assert_eq!(v["error"]["code"],"invalid_request");assert!(!s.root.join("context-protocol-fixture.called").exists());}}
#[test]fn legacy_wrappers_and_http_keep_exact_new_generation_stdin(){
 let s=Server::start();let cancel=std::sync::atomic::AtomicBool::new(false);let exe=std::path::Path::new(env!("CARGO_BIN_EXE_fake-cli-protocol-fixture"));
 for provider in ["codex","claude"]{
  assert!(moro_ai_bridge::provider::generate(provider,exe,"fixture:assert-legacy",&cancel,Duration::from_secs(5)).is_ok());
  assert!(moro_ai_bridge::provider::generate_with_context(provider,exe,"fixture:assert-legacy",None,&cancel,Duration::from_secs(5)).is_ok());
  let(code,v)=s.request("POST","/api/ai/jobs",&json!({"provider":provider,"prompt":"  fixture:assert-legacy  "}).to_string());assert_eq!(code,202,"{v}");assert_eq!(s.terminal(v["job"]["id"].as_str().unwrap())["status"],"succeeded");
 }
}
#[test]fn contextual_cancellation_keeps_no_late_result_or_base_context(){let s=Server::start();let(code,v)=s.request("POST","/api/ai/jobs",&json!({"provider":"codex","prompt":"fixture:slow","baseProject":project(),"contextConsent":true}).to_string());assert_eq!(code,202,"{v}");let id=v["job"]["id"].as_str().unwrap();let(code,v)=s.request("POST",&format!("/api/ai/jobs/{id}/cancel"),"{}");assert_eq!(code,200);assert_eq!(v["job"]["status"],"cancelled");std::thread::sleep(Duration::from_millis(100));let job=s.terminal(id);assert_eq!(job["status"],"cancelled");for field in ["project","baseProject","contextConsent"]{assert!(job.get(field).is_none());}assert!(!job.to_string().contains("Private context"));}
